    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue

        sign = '+' if coeff > 0 else '-'
        abs_coeff = abs(coeff)

        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
