def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1.")

    # Start checking from the smallest prime number
    factor = 2
    while factor * factor <= n:
        if n % factor == 0:
            # If factor is a factor of n, then n // factor is the larger prime factor
            return n // factor
        factor += 1

    # If no factors are found, n itself is a prime number
    return n

